import{_ as a,o as t,c as r,a2 as l}from"./chunks/framework.DT_qyuxR.js";const h=JSON.parse(`{"title":"🎪 Guide de l'Hôte du Carnaval","description":"","frontmatter":{},"headers":[],"relativePath":"gitbook/guide-joueur/04-guide-mj.md","filePath":"gitbook/guide-joueur/04-guide-mj.md"}`),s={name:"gitbook/guide-joueur/04-guide-mj.md"};function i(o,e,n,u,d,c){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="🎪-guide-de-l-hote-du-carnaval" tabindex="-1">🎪 Guide de l&#39;Hôte du Carnaval <a class="header-anchor" href="#🎪-guide-de-l-hote-du-carnaval" aria-label="Permalink to &quot;🎪 Guide de l&#39;Hôte du Carnaval&quot;">​</a></h1><h2 id="votre-role" tabindex="-1">Votre rôle <a class="header-anchor" href="#votre-role" aria-label="Permalink to &quot;Votre rôle&quot;">​</a></h2><p>Vous êtes l&#39;<strong>Hôte du Carnaval</strong> — le narrateur, l&#39;arbitre, le pilote de la partie. Vous ne jouez pas, vous faites vivre le jeu.</p><h2 id="setup-de-la-partie" tabindex="-1">Setup de la partie <a class="header-anchor" href="#setup-de-la-partie" aria-label="Permalink to &quot;Setup de la partie&quot;">​</a></h2><h3 id="_1-creer-la-partie" tabindex="-1">1. Créer la partie <a class="header-anchor" href="#_1-creer-la-partie" aria-label="Permalink to &quot;1. Créer la partie&quot;">​</a></h3><p>Utilisez la commande :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/carnival-nouvelle-partie</span></span></code></pre></div><p>Le bot crée :</p><ul><li>Un salon vocal pour chaque zone (La Grande Tente, La Foire aux Monstres, Le Cimetière des Caravanes).</li><li>Un salon texte pour les débats.</li><li>Un salon privé pour vous (l&#39;Hôte).</li></ul><h3 id="_2-inviter-les-joueurs" tabindex="-1">2. Inviter les joueurs <a class="header-anchor" href="#_2-inviter-les-joueurs" aria-label="Permalink to &quot;2. Inviter les joueurs&quot;">​</a></h3><p>Les joueurs rejoignent le salon vocal de leur choix. Le bot les détecte automatiquement.</p><h3 id="_3-verrouiller-la-composition" tabindex="-1">3. Verrouiller la composition <a class="header-anchor" href="#_3-verrouiller-la-composition" aria-label="Permalink to &quot;3. Verrouiller la composition&quot;">​</a></h3><p>Quand tous les joueurs sont présents :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/carnival-verrouiller-composition</span></span></code></pre></div><p>Le bot :</p><ul><li>Tire aléatoirement les camps (~1/3 Revenants).</li><li>Envoie à chaque joueur son camp et son pool de 3 masques en MP.</li><li>Les joueurs choisissent leur masque.</li></ul><h3 id="_4-valider-et-lancer" tabindex="-1">4. Valider et lancer <a class="header-anchor" href="#_4-valider-et-lancer" aria-label="Permalink to &quot;4. Valider et lancer&quot;">​</a></h3><p>Quand tous les joueurs ont choisi leur masque :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/carnival-lancer-partie</span></span></code></pre></div><p>La partie commence par la <strong>Nuit 1</strong>.</p><h2 id="pendant-la-partie" tabindex="-1">Pendant la partie <a class="header-anchor" href="#pendant-la-partie" aria-label="Permalink to &quot;Pendant la partie&quot;">​</a></h2><h3 id="phases" tabindex="-1">Phases <a class="header-anchor" href="#phases" aria-label="Permalink to &quot;Phases&quot;">​</a></h3><p>Le bot gère automatiquement les phases :</p><ol><li>🌙 <strong>Nuit</strong> : les joueurs envoient leurs actions en MP.</li><li>📢 <strong>Résolution</strong> : le bot affiche les résultats.</li><li>💬 <strong>Débats</strong> : discussion libre (5 minutes).</li><li>☀️ <strong>Actions de Jour</strong> : les joueurs utilisent leurs pouvoirs.</li><li>⚔️ <strong>Duels</strong> : les joueurs se défient.</li></ol><h3 id="avancer-les-phases" tabindex="-1">Avancer les phases <a class="header-anchor" href="#avancer-les-phases" aria-label="Permalink to &quot;Avancer les phases&quot;">​</a></h3><p>Le bot avance automatiquement les phases. Vous n&#39;avez rien à faire sauf si un joueur a un problème.</p><h3 id="arbitrage" tabindex="-1">Arbitrage <a class="header-anchor" href="#arbitrage" aria-label="Permalink to &quot;Arbitrage&quot;">​</a></h3><p>En tant qu&#39;Hôte, vous arbitrez les situations ambiguës :</p><ul><li>Un joueur a un problème technique ? Aidez-le.</li><li>Un joueur ne comprend pas une règle ? Expliquez-lui.</li><li>Un joueur conteste un résultat ? Vérifiez les logs.</li></ul><h2 id="commandes-utiles" tabindex="-1">Commandes utiles <a class="header-anchor" href="#commandes-utiles" aria-label="Permalink to &quot;Commandes utiles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Commande</th><th>Description</th></tr></thead><tbody><tr><td><code>/carnival-nouvelle-partie</code></td><td>Crée une nouvelle partie</td></tr><tr><td><code>/carnival-verrouiller-composition</code></td><td>Verrouille la composition et tire les camps</td></tr><tr><td><code>/carnival-lancer-partie</code></td><td>Lance la partie (Nuit 1)</td></tr><tr><td><code>/carnival-annuler-partie</code></td><td>Annule la partie en cours</td></tr><tr><td><code>/carnival-voir-logs</code></td><td>Affiche les logs de la partie</td></tr></tbody></table><h2 id="conseils-pour-l-hote" tabindex="-1">Conseils pour l&#39;Hôte <a class="header-anchor" href="#conseils-pour-l-hote" aria-label="Permalink to &quot;Conseils pour l&#39;Hôte&quot;">​</a></h2><h3 id="_1-lisez-les-regles" tabindex="-1">1. Lisez les règles <a class="header-anchor" href="#_1-lisez-les-regles" aria-label="Permalink to &quot;1. Lisez les règles&quot;">​</a></h3><p>Avant de lancer une partie, lisez toutes les règles. Vous devez tout comprendre.</p><h3 id="_2-soyez-neutre" tabindex="-1">2. Soyez neutre <a class="header-anchor" href="#_2-soyez-neutre" aria-label="Permalink to &quot;2. Soyez neutre&quot;">​</a></h3><p>Ne favorisez aucun camp. Ne révélez pas d&#39;informations.</p><h3 id="_3-gerez-le-temps" tabindex="-1">3. Gérez le temps <a class="header-anchor" href="#_3-gerez-le-temps" aria-label="Permalink to &quot;3. Gérez le temps&quot;">​</a></h3><p>Les Débats durent 5 minutes. Ne les laissez pas trop longtemps.</p><h3 id="_4-animez-le-jeu" tabindex="-1">4. Animez le jeu <a class="header-anchor" href="#_4-animez-le-jeu" aria-label="Permalink to &quot;4. Animez le jeu&quot;">​</a></h3><p>Utilisez des descriptions narratives pour créer l&#39;ambiance. Le Carnaval est un lieu sombre et fascinant.</p><h3 id="_5-gerez-les-duels" tabindex="-1">5. Gérez les Duels <a class="header-anchor" href="#_5-gerez-les-duels" aria-label="Permalink to &quot;5. Gérez les Duels&quot;">​</a></h3><p>Les Duels sont automatiques, mais vous devez surveiller les problèmes :</p><ul><li>Un joueur quitte le salon vocal pendant un Duel ?</li><li>Un joueur conteste le résultat ?</li><li>Un bug technique ?</li></ul><h2 id="en-cas-de-probleme" tabindex="-1">En cas de problème <a class="header-anchor" href="#en-cas-de-probleme" aria-label="Permalink to &quot;En cas de problème&quot;">​</a></h2><h3 id="bug-technique" tabindex="-1">Bug technique <a class="header-anchor" href="#bug-technique" aria-label="Permalink to &quot;Bug technique&quot;">​</a></h3><p>Si le bot plante, redémarrez-le et utilisez <code>/carnival-voir-logs</code> pour comprendre le problème.</p><h3 id="joueur-absent" tabindex="-1">Joueur absent <a class="header-anchor" href="#joueur-absent" aria-label="Permalink to &quot;Joueur absent&quot;">​</a></h3><p>Si un joueur est absent pendant longtemps, vous pouvez l&#39;éliminer (son masque est brisé, son identité est révélée).</p><h3 id="contestations" tabindex="-1">Contestations <a class="header-anchor" href="#contestations" aria-label="Permalink to &quot;Contestations&quot;">​</a></h3><p>Si un joueur conteste un résultat, vérifiez les logs et expliquez la règle. En cas de doute, votre décision est finale.</p>',50)])])}const m=a(s,[["render",i]]);export{h as __pageData,m as default};
